mapper.select:
SELECT id, order_id AS orderId, customer_name AS customer, worker_name AS worker, score, tags, content, created_time AS createdTime, CASE type WHEN 'COMPLAINT' THEN '投诉' ELSE '评价' END AS type, CASE status WHEN 'PENDING' THEN '待处理' WHEN 'PROCESSING' THEN '处理中' WHEN 'VISITED' THEN '已回访' WHEN 'CLOSED' THEN '已闭环' ELSE status END AS status, DATE_FORMAT(FROM_UNIXTIME(created_time/1000), '%Y-%m-%d %H:%i') AS time FROM review WHERE 1 = 1
AND type = #{type}
AND status = #{status}
ORDER BY created_time DESC LIMIT 300
